import{_ as a,o as i,c as e,a3 as t}from"./chunks/framework.BJ2rlPXv.js";const k=JSON.parse('{"title":"allow","description":"","frontmatter":{},"headers":[],"relativePath":"cli/allow.md","filePath":"cli/allow.md","lastUpdated":1795654473000}'),l={name:"cli/allow.md"};function n(o,s,p,h,d,r){return i(),e("div",null,[...s[0]||(s[0]=[t(`<h1 id="allow" tabindex="-1">allow <a class="header-anchor" href="#allow" aria-label="Permalink to &quot;allow&quot;">​</a></h1><p>Allow servers for agents. The MCP server (<code>lazyapi mcp</code>) asks before sending a request to a server nobody allowed; <code>allow</code> answers ahead of time, lists the answers and takes them back. It is meant for people: agents are told to ask you instead of running it.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#1E66F5;--shiki-light-font-style:italic;--shiki-dark:#89B4FA;--shiki-dark-font-style:italic;">lazyapi</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> allow</span><span style="--shiki-light:#179299;--shiki-dark:#94E2D5;"> &lt;</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;">origi</span><span style="--shiki-light:#4C4F69;--shiki-dark:#CDD6F4;">n</span><span style="--shiki-light:#179299;--shiki-dark:#94E2D5;">&gt;</span><span style="--shiki-light:#4C4F69;--shiki-dark:#CDD6F4;"> [--writes]</span></span>
<span class="line"><span style="--shiki-light:#1E66F5;--shiki-light-font-style:italic;--shiki-dark:#89B4FA;--shiki-dark-font-style:italic;">lazyapi</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> allow</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> --list</span></span>
<span class="line"><span style="--shiki-light:#1E66F5;--shiki-light-font-style:italic;--shiki-dark:#89B4FA;--shiki-dark-font-style:italic;">lazyapi</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> allow</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> --revoke</span><span style="--shiki-light:#179299;--shiki-dark:#94E2D5;"> &lt;</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;">origi</span><span style="--shiki-light:#4C4F69;--shiki-dark:#CDD6F4;">n</span><span style="--shiki-light:#179299;--shiki-dark:#94E2D5;">&gt;</span></span></code></pre></div><p>An origin is <code>scheme://host[:port]</code> — <code>https://api.example.com</code> is <code>https://api.example.com:443</code>, a bare <code>api.example.com:8443</code> means HTTPS — or <code>localhost</code> for every server on this machine (<code>localhost</code>, <code>127.0.0.1</code>, <code>::1</code>, <code>*.localhost</code>, any port).</p><table tabindex="0"><thead><tr><th>Flag</th><th>Meaning</th></tr></thead><tbody><tr><td><code>--writes</code></td><td>also allow POST, PUT, PATCH, DELETE… (without it: GET, HEAD and OPTIONS only; <code>localhost</code> always allows both)</td></tr><tr><td><code>--list</code></td><td>list the remembered origins and what they allow</td></tr><tr><td><code>--revoke</code></td><td>forget an origin</td></tr></tbody></table><div class="language-console vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">console</span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#7C7F93;--shiki-dark:#9399B2;">$</span><span style="--shiki-light:#4C4F69;--shiki-dark:#CDD6F4;"> lazyapi allow localhost</span></span>
<span class="line"><span style="--shiki-light:#4C4F69;--shiki-dark:#CDD6F4;">Allowed localhost for reads and writes (/home/ana/.config/lazyapi/permissions.json)</span></span>
<span class="line"><span style="--shiki-light:#7C7F93;--shiki-dark:#9399B2;">$</span><span style="--shiki-light:#4C4F69;--shiki-dark:#CDD6F4;"> lazyapi allow https://staging.example.com --writes</span></span>
<span class="line"><span style="--shiki-light:#4C4F69;--shiki-dark:#CDD6F4;">Allowed https://staging.example.com:443 for reads and writes (…)</span></span>
<span class="line"><span style="--shiki-light:#7C7F93;--shiki-dark:#9399B2;">$</span><span style="--shiki-light:#4C4F69;--shiki-dark:#CDD6F4;"> lazyapi allow --list</span></span>
<span class="line"><span style="--shiki-light:#4C4F69;--shiki-dark:#CDD6F4;">https://staging.example.com:443          reads and writes  since 2026-11-26</span></span>
<span class="line"><span style="--shiki-light:#4C4F69;--shiki-dark:#CDD6F4;">localhost                                reads and writes  since 2026-11-26</span></span></code></pre></div><p>The answers are stored in your config directory (<code>$XDG_CONFIG_HOME/lazyapi/permissions.json</code>, <code>~/Library/Application Support/lazyapi/</code> on macOS, <code>%AppData%\\lazyapi\\</code> on Windows; <code>$LAZYAPI_PERMISSIONS</code> overrides the file), mode <code>600</code>, never in the project. A running MCP server sees changes at once. Answers given in the agent (&quot;always&quot;) land in the same file.</p><p>See <a href="/v2/agents#permissions-the-agent-only-calls-servers-you-allow">permissions</a> for how the MCP server asks.</p>`,8)])])}const g=a(l,[["render",n]]);export{k as __pageData,g as default};
